-- ============================================================================
-- RC7 ASSOCIATE DEEP SEED: Well Test Analysis, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, so the seeded structure and the
-- shipped lesson files cannot disagree.
--
-- What this tier owns: the classical straight line. What a well test measures
-- and what it only infers; the semilog slope and the flow capacity it
-- determines before any thickness is divided out; skin as a residual read off
-- the line's POSITION, and the pressure and flow efficiency it converts to;
-- Horner, MDH, Agarwal equivalent time and p star; and then the window walk,
-- where the same forty shut-in pressures fitted five ways move the
-- permeability by a factor of 3.6750288362649663 and invert the sign of the
-- skin while r squared climbs to 0.9997.
--
-- Every number in the lessons is derived by running the vendored
-- engines/welltest against test-data/welltest/goldens.json, and the teaching
-- lab that the panel and this course share is pinned to the same values by
-- welltestLab.test.js. A numeric sweep over the lessons resolved all 155
-- literals carrying seven or more significant figures to an engine-derived
-- value; a tier-leakage sweep over the lessons and the banks reports zero
-- downward leaks and zero same-tier answer prints against all eighteen
-- graded fields.
--
-- Answer keys live only here and in academy_quiz_questions, which has no
-- client SELECT policy.
-- ============================================================================

values ('welltest', 'beginner', '{"modules":[{"key":"m01-what-a-well-test-is","title":"What a Well Test Is","lesson_keys":["l01-a-controlled-disturbance","l02-drawdown-and-buildup","l03-the-well-this-course-analyses","l04-what-the-answer-is-for"]},{"key":"m02-the-radial-straight-line","title":"The Radial Straight Line","lesson_keys":["l01-why-pressure-is-linear-in-log-time","l02-the-semilog-slope","l03-permeability-from-the-slope","l04-the-thickness-you-divide-by","l05-what-the-line-is-not"]},{"key":"m03-skin","title":"Skin","lesson_keys":["l01-what-skin-is","l02-skin-from-the-one-hour-pressure","l03-the-pressure-skin-costs","l04-flow-efficiency","l05-skin-is-not-damage"]},{"key":"m04-buildup-horner-and-mdh","title":"Buildup: Horner and MDH","lesson_keys":["l01-superposition-in-one-picture","l02-horner-time-runs-backwards","l03-p-star-and-average-pressure","l04-mdh-and-agarwal","l05-the-two-analyses-disagree"]},{"key":"m05-choosing-the-line","title":"Choosing the Line","lesson_keys":["l01-wellbore-storage","l02-the-window-walk","l03-the-sign-of-the-skin-inverts","l04-r-squared-does-not-protect-you"]},{"key":"m06-the-associate-reading","title":"The Associate Reading","lesson_keys":["l01-the-story-so-far","l02-working-the-capstone","l03-onward"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
      updated_at = now();

delete from public.academy_quiz_questions
 where app_slug = 'welltest' and tier = 'beginner';

