insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 1, 'What is the raw dataset of a well test?', '["A permeability, a skin factor and an extrapolated pressure, which the gauge computes downhole and stores.", "A set of stabilised flowing pressures at several rates, from which the well''s deliverability follows directly.", "A pressure history against time, next to a record of what the well was doing.", "A sequence of fluid samples taken at intervals through the test, analysed afterwards in a laboratory."]'::jsonb, 2, 'Permeability and skin are inferred afterwards from the shape of that history. Nothing in the well measures either of them, which is why two engineers can hand you different answers from one file.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 2, 'Why does a well test have to disturb the reservoir?', '["A reservoir at rest gives you its pressure and nothing else, so learning how easily fluid moves requires making it move.", "Because the gauge cannot resolve a static pressure accurately enough to be useful for reservoir engineering.", "Because the disturbance is what pushes the fluid contact far enough for the test to see it clearly.", "Because a static measurement is dominated by the wellbore fluid column rather than by the formation."]'::jsonb, 0, 'Change the rate, hold the new rate steady, and watch what the pressure does about it. The response carries the wellbore, the near-well damage, the rock and eventually the boundaries.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 3, 'How does the radius the transient has reached grow with time?', '["Linearly, so doubling the test length doubles the radius investigated and the volume seen.", "As the square root of time, so doubling the test length multiplies it by about 1.41.", "As the logarithm of time, so each extra decade of test adds the same increment of radius.", "As the cube root of time, because the disturbance spreads through a volume rather than across an area."]'::jsonb, 1, 'That square root is why long tests are expensive in a specific way: the last doubling of test time buys much less new rock than the first.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 4, 'A rate recorded as 450 stb/d was really 500. What happens to the reported permeability?', '["It is unaffected, since the rate cancels between the slope and the skin term in the analysis.", "It is wrong by the square of the proportion, because the rate appears both in the slope and in the pressure drop.", "It is wrong only if the error persisted for the whole test; a rate error in one period averages out.", "It is wrong by exactly the same proportion, silently, because rate enters the permeability linearly."]'::jsonb, 3, 'The slope equation carries q in the numerator. No amount of care in the analysis recovers a rate error, which is why the rate record is checked before the pressure record.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 5, 'Where is the gauge supposed to sit, and why?', '["Downhole, because a surface pressure converted through a changing fluid column carries the errors of that conversion.", "At surface, because a downhole gauge disturbs the flow geometry near the perforations it is measuring.", "At the separator, because that is where the rate is metered and the two records must share a reference.", "Anywhere in the tubing, because the analysis works on pressure DIFFERENCES and a constant offset cancels."]'::jsonb, 0, 'A constant offset would indeed cancel, and that is the point: the offset from a changing column is not constant, so it does not.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 6, 'Roughly which part of a pressure history carries information about the boundaries?', '["The earliest data, because a boundary sets the pressure the whole system is drawing towards from the first instant.", "The latest data, because the disturbance has to travel outward before it can reach anything.", "The middle data, where radial flow is established and the geometry is best defined.", "All of it equally, since a boundary changes the whole solution rather than only its late part."]'::jsonb, 1, 'Earliest is the wellbore, middle is the rock, latest is whatever the transient reached. That ordering is what makes a regime sequence readable.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 7, 'Why is skin quoted as a dimensionless number rather than as a pressure?', '["Because the pressure it costs cannot be computed without knowing the damaged zone''s thickness and permeability separately.", "Because pressure units differ between operating companies and a dimensionless form avoids the conversion.", "So that it is a property of the well rather than of the rate the test happened to be run at.", "Because the skin is a ratio of two pressures and therefore has no units to begin with."]'::jsonb, 2, 'Double the rate and the skin pressure drop doubles while the skin factor does not. That is what makes it comparable between wells and over time.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 8, 'A well takes two hours to stop flowing after the surface valve is closed. What is that called?', '["Afterflow damping, which is a gauge response artefact rather than a reservoir or wellbore effect.", "Rate transience, which is handled by superposing the recorded surface rate history in the analysis.", "Sandface lag, a delay in the pressure signal reaching the gauge through the column.", "Wellbore storage, and it means the early data describe the wellbore rather than the reservoir."]'::jsonb, 3, 'It is the single most common cause of a well test being read wrong, and it is the subject of the fifth module of this tier.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 9, 'Which is the honest description of what a well test report contains?', '["A pressure history, which is data, and an interpretation of it, which is not.", "Two independent measurements, of flow capacity and of near-well damage, each with its own error bar.", "A calibrated model of the reservoir, since the analysis is validated against the recorded pressures.", "A set of hard numbers whose uncertainty comes almost entirely from the gauge specification."]'::jsonb, 0, 'A report that hands over a permeability without the pressure plot, the fitted window and the assumed model has hidden the part that could be checked.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 10, 'What does a positive skin cost a producing well?', '["A reduced drainage radius, because the damaged zone cuts the well off from the outer reservoir.", "An extra pressure drop at every barrel, paid across a thin zone around the wellbore.", "A lower reservoir permeability in the analysis, which is where the damage shows up numerically.", "A delay before radial flow begins, which shortens the usable part of the test."]'::jsonb, 1, 'Removing it entirely would let the well produce the same rate at a higher flowing pressure, or a higher rate at the same one. That is what makes it worth money.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 11, 'Why does a well test measure a much larger volume than a core or a log?', '["Because the flowing fluid physically sweeps the drainage volume and carries its properties to the well.", "Because the gauge integrates the pressure over the whole open interval rather than sampling one depth.", "Because the pressure disturbance spreads hundreds or thousands of feet from the well during the test.", "Because the analysis averages many measurements, and averaging reduces the volume-scale uncertainty."]'::jsonb, 2, 'It is still a small fraction of a field, and the average it returns is weighted in a way that is not simple.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 12, 'Which of these does a pressure transient NOT determine?', '["Flow capacity, which is the product of permeability and thickness that the semilog slope gives.", "Skin, which is the residual pressure drop the ideal radial solution does not explain.", "The extrapolated pressure, which is what the fitted line reaches at infinite shut-in.", "Porosity, which enters the equations as an input taken from logs and cores."]'::jsonb, 3, 'The test cannot separate porosity from compressibility. Both appear in the same group, and both are supplied from outside.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 13, 'What is the practical consequence of the interpretation being a choice?', '["Two competent engineers can report different permeabilities from one file without either making an error.", "The reported answer depends on the software vendor, since each implements the equations differently.", "Results have to be reported as ranges, which is why single permeability values are no longer quoted.", "The analysis must always be repeated by a second engineer before the result can be issued."]'::jsonb, 0, 'The equations are the same everywhere. What differs is which points went into them, and that is a decision rather than a calculation.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 14, 'Why does this course use synthetic fixtures with known answers?', '["Because real well test data are commercially confidential and cannot be distributed in a course.", "Because holding what an analysis reports against what is actually there is the only way to see an interpretation error.", "Because synthetic data are noise-free, and noise is the main source of error in real interpretations.", "Because the engine can only evaluate its own analytical solutions and cannot read a real gauge file."]'::jsonb, 1, 'The analyses run on a fixture are the same analyses that run on a real test, and the mistakes they make are the same mistakes. Here you can see them.'),
  ('welltest', 'beginner', 'module', 'm01-what-a-well-test-is', 15, 'A gauge reads 3 psi high at every single point of a test. What happens to the permeability?', '["It rises by the ratio of 3 psi to the total drawdown, because the drawdown appears in the denominator.", "It falls, because the apparent pressure drop is smaller and a smaller drop implies better rock.", "Nothing, because the analysis uses pressure differences and a constant offset cancels out of them.", "It is unaffected but the skin is, since the skin uses an absolute pressure rather than a difference."]'::jsonb, 2, 'The skin uses a difference too: the line''s value at one hour minus the flowing pressure at shut-in. A constant offset cancels from both.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 1, 'Why is pressure linear in the logarithm of time during radial flow?', '["Because the diffusivity equation is solved by separation of variables, which produces a logarithm.", "Each doubling of the disturbed radius adds the same pressure increment, and radius grows as the square root of time.", "Because the fluid is slightly compressible, and a slightly compressible fluid expands logarithmically as pressure falls.", "Because the gauge samples logarithmically, so the plotted relationship inherits the sampling."]'::jsonb, 1, 'Equal pressure increments for equal ratios of radius, and equal ratios of radius for equal ratios of time. That is a logarithm, and it is why the semilog plot exists.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 2, 'What does the semilog slope contain?', '["Rate, viscosity, permeability, thickness and skin, which is why a damaged well shows a steeper line.", "Permeability, porosity, compressibility and wellbore radius, the four that set how fast the transient spreads.", "Rate, formation volume factor, viscosity, permeability and thickness, and nothing else.", "Everything the reservoir description contains, which is why a slope alone determines the whole answer."]'::jsonb, 2, 'Porosity, compressibility, skin and wellbore radius are absent. The slope is a statement about flow capacity, and everything else comes from where the line sits.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 3, 'The slope for this reservoir at the planted 85 mD is 21.520588235294117 psi per cycle. What does a fit returning 79.08878233809047 tell you?', '["That the fitted line is not on radial flow, because a slope nearly four times too steep is not a permeability question.", "That the permeability is nearly four times the planted value, since slope and permeability move together.", "That the rate used in the analysis was nearly four times too small, which is the only input that scales the slope.", "That the thickness is wrong, since thickness is the only other quantity in the slope equation."]'::jsonb, 0, 'It comes from fitting every point of the buildup, most of which are storage-affected and steeper than radial flow. Nothing is wrong with the inputs.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 4, 'What does the test actually determine, before any division?', '["The permeability k, which is then multiplied by a thickness to give a flow capacity for the simulator.", "The transmissibility kh divided by viscosity, since viscosity and thickness always appear together.", "The mobility k over viscosity, since the equations cannot separate the rock from the fluid.", "The flow capacity kh, in millidarcy feet, which needs no thickness at all."]'::jsonb, 3, 'Look at the rearranged slope equation: kh equals 162.6 q B mu over m, with no h on the right. Splitting kh into a permeability is a second step you make with a log in your hand.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 5, 'A net pay revised from 45 ft to 36 ft does what to a reported permeability?', '["Lowers it by a fifth, because permeability is proportional to the thickness it is spread over.", "Raises it by a quarter, while the flow capacity that the test actually measured does not change at all.", "Leaves it alone, because the analysis fits the pressure history rather than a thickness-dependent quantity.", "Raises it by a fifth, since the same capacity is now attributed to a proportionally thinner interval."]'::jsonb, 1, 'Permeability is inversely proportional to h. Report the kh and the thickness used, so a reader holding a revised net pay can redo the division.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 6, 'Which thickness does the slope equation want?', '["The gross interval from top to base of the formation, since the transient does not respect cut-offs.", "The completed interval, because that is the part of the well open to the reservoir and therefore flowing.", "Net pay, the part of the interval that actually flows, from the petrophysical interpretation.", "The perforated height corrected for the deviation angle, which is the true vertical extent contributing."]'::jsonb, 2, 'Using the completed interval instead inflates the permeability and hides a real skin, and both errors point the same way: better rock and a less damaged well than you have.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 7, 'What is the first condition under which the semilog straight line stops being valid?', '["The flow into the well is coming from the wellbore''s own volume rather than from the reservoir.", "The rate has changed during the test, which puts a discontinuity in the pressure history.", "The reservoir pressure has fallen below the bubble point, so a second phase is present near the well.", "The gauge resolution is coarser than the pressure change over one logarithmic cycle."]'::jsonb, 0, 'Wellbore storage. It is first in the list because it is first in time, and it is why the early data are excluded from every semilog fit in this course.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 8, 'Two wells in the same reservoir show slopes of 22 and 44 psi per cycle at 450 and 900 stb/d. What follows?', '["The second well is in rock half as permeable, since its slope is twice as steep.", "The two wells have the same flow capacity, which follows immediately from the slope equation.", "The second well has twice the skin, because doubling the rate doubles the skin pressure drop.", "Nothing about the permeabilities yet, because the slope scales with rate and the two rates differ by the same factor."]'::jsonb, 3, 'Slope over rate is the quantity to compare, and it is the same for both. Whether the flow capacities match then depends on the two thicknesses and the two fluids.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 9, 'Where is the semilog straight line usually found in a buildup?', '["In the middle of the record, which is the standard convention when nothing else is known.", "In the late data, after storage and its transition have died and before any boundary is felt.", "In the early data, before boundaries have had time to affect the response.", "Across the whole record, which is why a least squares fit over everything is the default."]'::jsonb, 1, 'Bounded at both ends by physics rather than by position. On the buildup in this course it is thirteen points out of forty and they are at the end.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 10, 'What is the practical way to check that a semilog slope is plausible?', '["Check that the coefficient of determination exceeds 0.99, which rules out a badly chosen window.", "Confirm that the fitted line passes through the initial pressure at a time of one hour.", "Compare it against the slope a plausible permeability would give for this rate, fluid and thickness.", "Verify that the slope is positive on a drawdown and negative on a buildup, which detects a sign error."]'::jsonb, 2, 'At a few hundred stb/d in tens of millidarcies over tens of feet, a few tens of psi per cycle is normal. A slope of 0.2 or of 2000 means the inputs are wrong.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 11, 'Why does a damaged well not show a steeper semilog line?', '["Because skin adds a constant pressure drop once radial flow is established, which shifts the line without tilting it.", "Because skin is dimensionless and therefore cannot contribute to a slope that carries units of psi per cycle.", "Because the damaged zone is thin, so its contribution decays within the first few minutes of the test.", "Because the skin''s effect is absorbed into the extrapolated pressure rather than appearing in the data."]'::jsonb, 0, 'Slope gives permeability, position gives skin. Keeping the two separate is what makes one line yield two answers.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 12, 'How much of a well test contributes to the permeability determination?', '["Every recorded point, since a least squares fit weights all the data that were supplied to it.", "One number, the steepness of one line drawn through a fraction of the points recorded.", "Two numbers, the slope and the intercept, because the permeability equation happens to use both.", "The whole pressure history, through the model that is fitted to it in modern practice."]'::jsonb, 1, 'Thousands of readings and days of deferred production, and the permeability is the slope. That is worth remembering when deciding how much care the window deserves.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 13, 'Why is 162.6 not derivable at the desk?', '["It is an empirical constant fitted to field data, and different regions use slightly different values.", "It depends on the fluid, so it has to be looked up for the oil in question before an analysis.", "It is derivable, but only from the exponential integral''s series expansion at large argument.", "It is a unit conversion with the solution''s constants folded into it, specific to oilfield units."]'::jsonb, 3, 'The defence is a sanity check on the resulting slope rather than a derivation. Getting the units wrong produces a slope that is absurd rather than subtly off.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 14, 'What does ''infinite acting'' mean?', '["The reservoir has no boundaries at all anywhere, which is an idealisation no real reservoir satisfies.", "The pressure response will continue indefinitely without ever reaching a steady state.", "The disturbance is spreading freely and has not yet reached anything that changes the geometry.", "The test is long enough that the wellbore no longer influences the measured response."]'::jsonb, 2, 'It is a statement about the test, not about the reservoir. Every reservoir stops acting infinite eventually, and what it does next is the Professional tier''s subject.'),
  ('welltest', 'beginner', 'module', 'm02-the-radial-straight-line', 15, 'A well is completed across 20 ft of a 45 ft sand. Which thickness goes in the slope equation?', '["45 ft, because once radial flow is established the well drains the whole sand.", "20 ft, because that is where fluid actually enters the wellbore.", "Something between the two, weighted by the vertical to horizontal permeability ratio.", "20 ft for the early data and 45 ft for the late data, since the flow geometry changes during the test."]'::jsonb, 0, 'The restricted entry shows up as an extra positive skin instead. Using 20 ft inflates the permeability and hides that skin at the same time.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 1, 'What does the skin factor represent?', '["The thickness of the damaged annulus around the wellbore, expressed in wellbore radii rather than in feet.", "The pressure drop the ideal radial solution failed to predict, collected into one dimensionless number.", "The ratio of the damaged zone''s permeability to the reservoir''s, which is what an acid job changes.", "The fraction of the drawdown that is lost near the well."]'::jsonb, 1, 'Van Everdingen and Hurst put the whole near-well effect into one additive term rather than modelling the annulus. Infinitely many combinations of zone thickness and permeability give the same skin.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 2, 'Why can a skin factor not tell you how thick the damaged zone is?', '["Because a thin badly damaged zone and a thick mildly damaged one produce the same pressure drop.", "Because the zone''s thickness is smaller than the resolution of any downhole pressure gauge in use.", "Because the skin is measured at the sandface, where the zone''s outer boundary is not yet felt by the transient.", "Because thickness cancels out of the diffusivity equation when the equation is made dimensionless."]'::jsonb, 0, 'The skin combines the two into one number and no pressure transient separates them. That is the price of the convenience of a single dimensionless residual.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 3, 'What is the equivalent wellbore radius of a well with skin S?', '["The actual radius divided by S, which is why a skin of zero corresponds to an undamaged well of any radius.", "The actual radius plus the thickness of the damaged annulus, which is what the transient effectively sees.", "The actual radius multiplied by the exponential of minus S.", "The actual radius multiplied by S, so a skin of 6.5 corresponds to a well six and a half times larger."]'::jsonb, 2, 'A positive skin behaves like a smaller well, a negative one like a larger. A fracture of half-length 250 ft behaves roughly like a wellbore of half that, which is a skin around minus 5 or minus 6.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 4, 'Why does the model catalog bound the skin at zero for the fault and dual-porosity models?', '["Because a stimulated well cannot exist near a sealing fault, since the fault limits the fracture''s extent.", "Because a negative skin would make the Laplace inversion numerically unstable at the required precision.", "Because negative skins are rare enough that the extra parameter range is not worth the code.", "Because the effective-radius mapping that handles a negative skin does not commute with image wells or fissure functions."]'::jsonb, 3, 'Stimulated vertical wells belong to the homogeneous model, which handles a negative skin by the effective-radius route, or to a fracture model that represents the stimulation explicitly.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 5, 'Where in the data does the skin show up?', '["In the position of the semilog line rather than its steepness, because a constant pressure drop shifts without tilting.", "In the curvature of the early data, which is where the damaged annulus dominates the response.", "In the difference between the drawdown and the buildup analyses of the same well.", "In the slope, which is why a damaged well shows a steeper semilog line than an undamaged one."]'::jsonb, 0, 'Slope gives permeability, position gives skin. That split is why one line yields two answers, and the position is much more sensitive to the window than the slope is.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 6, 'The buildup skin formula uses which pressure difference?', '["The initial pressure minus the line''s value at one hour, which is the drawdown form of the same expression.", "The line''s value at one hour of shut-in minus the flowing pressure at the instant of shut-in.", "The measured shut-in pressure at one hour minus the flowing pressure at the moment the valve closed.", "The extrapolated pressure minus the pressure at one hour."]'::jsonb, 1, 'The drawdown form uses the initial pressure and the drawdown''s one-hour line value. Swapping them is a standard error and it does not produce an obviously silly number.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 7, 'Why must the one-hour pressure be read off the fitted line rather than off the data?', '["Because the gauge is sampling too coarsely at one hour to give a reliable single reading.", "Because the data at one hour carry the skin already, which would double-count it in the formula.", "Because at one hour the well is still storage-dominated, so the measured pressure is nowhere near the line.", "Because a measured value would make the reported skin depend on the gauge sampling interval rather than on the well itself."]'::jsonb, 2, 'The engine computes it as the intercept plus the slope times the logarithm of tp plus one, which is the line''s value. Reading the data instead produces skins that are wildly wrong.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 8, 'Why is one hour the reference time?', '["Because one hour is when radial flow typically begins in a well of this size and permeability.", "Because the damaged zone''s transient response has decayed by then in almost every well.", "Because gauge drift is negligible over the first hour, so the reading is at its most reliable.", "It is a convention, chosen because the logarithm of one is zero so the line''s value there is its intercept."]'::jsonb, 3, 'Nothing physical about it. On a Horner axis with a 36-hour producing time, one hour of shut-in sits at a ratio of exactly 37, and the reference point moves with the producing time.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 9, 'The skin pressure drop is proportional to which of these?', '["The square of the rate, because the near-well velocity and the pressure drop both scale with it.", "The rate, so the same skin costs twice as much pressure at twice the rate.", "The logarithm of the rate, following the same form as the semilog solution it comes from.", "Nothing to do with the rate, since skin is defined to be a rate-independent property of the well."]'::jsonb, 1, 'The skin FACTOR is rate-independent; the pressure it costs is not. That is why damage matters more on good wells than on poor ones.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 10, 'At the planted values, the skin costs 121.47352941176467 psi against a total drawdown of about 269. What does that say?', '["Roughly 45 percent of the pressure being spent to produce this well is spent crossing the damaged zone.", "The well is producing at about 45 percent of the rate an undamaged well would deliver at this drawdown.", "The reservoir pressure has fallen 121 psi since the well was completed, which is depletion rather than damage.", "About 45 percent of the reservoir''s flow capacity is unavailable because the damaged zone blocks it."]'::jsonb, 0, 'It is a pressure statement, not a rate statement. Converting it into a rate gain needs the productivity index and the assumption that productivity is proportional to drawdown.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 11, 'What is flow efficiency?', '["The ratio of the well''s actual measured rate to the rate it would deliver at the same drawdown with no skin at all.", "The fraction of the reservoir''s flow capacity that the completion actually connects to.", "The fraction of the total pressure drop that does useful work in the reservoir rather than crossing the skin.", "One minus the ratio of the skin factor to the total dimensionless pressure drop at the well."]'::jsonb, 2, 'It is the same information as the skin expressed as a fraction, and it is the form a decision is made in. A damage ratio carries the same information and behaves badly, because it runs to infinity.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 12, 'Which average pressure does a buildup actually give you for the flow efficiency calculation?', '["The average pressure directly, which is what the buildup converges to given enough shut-in time.", "The initial pressure, since the buildup recovers towards it in an infinite-acting reservoir.", "The pressure at the last recorded point, which is the closest measurement to the average.", "p star, the extrapolation of the semilog line, which sits above the true average pressure once a reservoir is bounded and produced."]'::jsonb, 3, 'For a well early in its life in a large reservoir, p star is a good approximation and using it is standard. For a small produced compartment it flatters the flow efficiency.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 13, 'Which of these produces a positive skin without any formation damage?', '["A deviated well, because the longer sandface exposes more of the damaged zone to flow.", "Partial penetration, because flow has to converge vertically to reach a restricted completion.", "A high total compressibility, because it slows the transient and mimics a near-well restriction.", "A large wellbore radius, because it reduces the pressure gradient at the sandface."]'::jsonb, 1, 'Deviation gives a NEGATIVE pseudoskin, typically minus 1 to minus 3, which can mask real damage. Partial penetration, non-Darcy flow and phase effects all give positive contributions.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 14, 'Why is a skin that changes with rate a useful observation?', '["Because a rate-dependent component means non-Darcy flow, which an acid job will not fix.", "Because it shows the gauge is drifting between the tests, which invalidates the comparison.", "Because it means the damaged zone is being eroded by the flow, so the skin will fall over time.", "Because it indicates the analysis used the wrong thickness in at least one of the tests."]'::jsonb, 0, 'The apparent skin is the real skin plus a rate-dependent term. Separating them needs two rates, and the engine returns only the sum, which is why this course grades nothing about the separation.'),
  ('welltest', 'beginner', 'module', 'm03-skin', 15, 'What should be reported alongside a flow efficiency?', '["The coefficient of determination of the fit, so a reader can judge how well the line described the points.", "The damage ratio as well, since some readers prefer it and the two carry different information.", "The skin pressure drop in psi, because a ratio discards the scale and the intervention economics need it.", "The gauge resolution, since flow efficiency is a small difference of two similar pressures."]'::jsonb, 2, 'A flow efficiency of 0.5 on a 50 stb/d well and on a 5000 stb/d well are the same number and completely different decisions.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 1, 'In the superposition picture of a buildup, what is the second, imaginary well doing?', '["Injecting at exactly the same rate as the producer, starting at the instant the well was shut in.", "Producing at the same rate as the original well from time zero, so that the two responses reinforce each other.", "Injecting from time zero at a rate that makes the net rate match the record.", "Producing at the difference between the two rates, which makes a rate change rather than a shut-in."]'::jsonb, 0, 'Before the shut-in only the producer exists. After it the two rates cancel at the well and the recovery is the sum of the producer''s continuing decline and the injector''s rising response.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 2, 'Why does a buildup carry the production history that preceded it?', '["Because the reservoir pressure has fallen during production, so the buildup starts from a lower baseline than a fresh test would.", "Because the fluid saturations near the well change during production and take time to redistribute after shut-in.", "Because the superimposed producer''s response depends on how long it has been producing, which is tp plus the shut-in time.", "Because the gauge records a cumulative rather than an instantaneous pressure."]'::jsonb, 2, 'Change tp and the whole buildup changes shape. That is why a buildup is not a fresh experiment and why the Horner axis has tp in it.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 3, 'What is the Horner time ratio?', '["The shut-in time divided by the producing time, which runs from zero towards one as the test proceeds.", "The producing time plus the shut-in time, divided by the shut-in time.", "The producing time divided by the shut-in time, which is the approximation valid when tp is much larger.", "The ratio of the flowing pressure at shut-in to the extrapolated pressure at infinite shut-in time."]'::jsonb, 1, 'It runs from a large number at early shut-in down towards 1 at long shut-in, which is why Horner plots are drawn with the axis reversed so that time still reads left to right.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 4, 'Why can the Horner ratio never reach 1?', '["Because the gauge resolution sets a floor on how small a Horner ratio can be distinguished.", "Because the reservoir reaches equilibrium first, after which the pressure no longer changes.", "Because the producing time is always at least as long as any practical shut-in, so the ratio stays above 2.", "Because the shut-in time would have to be infinite for the producing time to become negligible beside it."]'::jsonb, 3, 'That is exactly why the extrapolation to a ratio of 1 has meaning: it is the pressure after an infinite shut-in, which is p star, and it is finite because the axis is logarithmic.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 5, 'One hour of shut-in after 36 hours of production sits at which Horner ratio?', '["Exactly 37.", "Exactly 36, since the shut-in hour is negligible against the producing time and the ratio reduces to tp over dt.", "Exactly 35, because the convention subtracts the reference hour from the producing time before forming the ratio.", "It depends on the permeability, since the Horner axis is defined in dimensionless rather than in real time."]'::jsonb, 0, 'The reference point is not a fixed place on the plot. Two tests on the same well with different producing times put their one-hour reference at different Horner ratios.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 6, 'What is p star?', '["The initial pressure of the reservoir, recovered by the buildup once the transient has fully decayed.", "The average pressure of the drainage volume, which is what material balance calculations require.", "The pressure the fitted semilog line reaches when extrapolated to a Horner ratio of one.", "The highest pressure recorded during the shut-in, taken as the static pressure."]'::jsonb, 2, 'It is a property of the LINE, not of the reservoir. Change the window and it moves, and it is defined for any fitted line whether or not the line was the right one.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 7, 'In a bounded, produced reservoir, where does p star sit relative to the average pressure?', '["Below it, because the finite shut-in has not allowed the pressure to recover fully towards the average.", "Above it, because extrapolating the infinite-acting line pretends the reservoir keeps supplying from a region that does not exist.", "At it, provided the shut-in lasted at least as long as the production that preceded it.", "Either side of it, depending on whether the well sits near the centre or the edge of the compartment."]'::jsonb, 1, 'The Matthews-Brons-Hazebroek and Dietz corrections convert p star to an average pressure using the drainage geometry. Neither is in this engine, and this course grades p star rather than the average.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 8, 'Why is the MDH plot only valid for a buildup when the producing time is much longer than the shut-in?', '["Because a long producing time is what allows the reservoir to reach the infinite-acting regime before shut-in.", "Because MDH ignores the storage transient, which is proportionally shorter in a long-producing well.", "Because the skin formula for MDH assumes the well was at pseudo-steady state before the valve closed.", "Because only then does the Horner ratio reduce to tp over dt, so the logarithm differs from log dt by a constant."]'::jsonb, 3, 'A constant shifts the line without tilting it, so the slope and therefore the permeability are unaffected while the intercept is. The buildup here fails that condition: 36 hours of production, over 79 of shut-in.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 9, 'What is Agarwal equivalent time?', '["The producing time times the shut-in time, divided by their sum.", "The shut-in time corrected for the storage coefficient, so that buildups from different wells can be compared.", "The elapsed time since the start of production, which is what a drawdown solution takes as its argument.", "The shut-in time scaled by the ratio of the current rate to the rate before shut-in, which is zero here."]'::jsonb, 0, 'For small shut-in times it is essentially the shut-in time itself. For large ones it saturates at the producing time and never exceeds it.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 10, 'What follows from Agarwal equivalent time being bounded above by the producing time?', '["A buildup analysed on equivalent time cannot resolve a boundary, since boundaries appear at late time.", "The derivative computed on equivalent time is compressed at late time and cannot be read there.", "A buildup can never investigate further into the reservoir than the production that preceded it.", "The extrapolated pressure is always below the initial pressure by an amount set by the producing time."]'::jsonb, 2, 'So extending a shut-in past a few times tp buys very little. If a test needs to reach a boundary, the PRODUCTION before the shut-in has to be long enough.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 11, 'Which time transform does the engine use to differentiate a buildup?', '["Shut-in time, since the derivative is a local quantity and does not need the superposition removed.", "Agarwal equivalent time, applied in an identical form to the model and to the data.", "Horner time, because that is the axis the semilog analysis is done on and consistency matters.", "Material-balance time, which is the general superposition time for any rate history."]'::jsonb, 1, 'Differentiating a buildup against raw shut-in time gives a derivative that droops at late time for reasons that have nothing to do with the reservoir.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 12, 'Analysed carefully over their late data, the drawdown and buildup of this well disagree on permeability by about one percent. What does that mean?', '["That one of the two analyses used the wrong window, since correct analyses of one well must agree.", "That the rate was not constant during the drawdown, which is the usual cause of such a gap.", "That the reservoir is heterogeneous over the volume the two tests investigated.", "That the disagreement is a normal property of two different measurements and a fair estimate of the analysis uncertainty."]'::jsonb, 3, 'The two tests are affected by storage differently, their time axes weight the late data differently, and they interrogate different volumes. Quoting both, as a range, is the honest report.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 13, 'What does a wrong producing time do to a Horner analysis?', '["It moves the extrapolated pressure by a great deal and the reported permeability very little.", "It moves the permeability a great deal and the extrapolated pressure very little, since the slope depends on tp directly.", "It moves both in proportion, since every point on the Horner axis shifts by the same factor.", "It moves neither, because tp cancels between the numerator and denominator of the Horner ratio."]'::jsonb, 0, 'That asymmetry is a useful diagnostic. A buildup whose permeability agrees with other estimates but whose extrapolated pressure looks wrong is pointing at the producing time.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 14, 'How many significant figures is a well test permeability actually known to?', '["Four or five, which is the precision the least squares fit reports and the reason software prints them.", "Two, or perhaps three on a very good dataset, which is why a stated range is the honest report.", "One, since the thickness alone carries twenty percent uncertainty and dominates everything else.", "It depends on the gauge, since the pressure resolution propagates directly into the slope."]'::jsonb, 1, 'Two valid analyses of this same well disagree in the second figure. A capstone asks for full precision to check that the analysis was run, which is a different purpose from a report.'),
  ('welltest', 'beginner', 'module', 'm04-buildup-horner-and-mdh', 15, 'The buildup''s flowing pressure at shut-in is 4530.771773811249 psia against an initial 4800. What is that difference?', '["The pressure the buildup will recover during the shut-in, which the extrapolation then confirms.", "The depletion suffered over the 36 hours of production before it.", "The total drawdown the well was producing under at the moment it was shut in.", "The skin pressure drop plus the storage contribution, which together make up the near-well loss."]'::jsonb, 2, 'Roughly 269 psi, of which the skin at the planted values accounts for about 121. The rest is the reservoir''s own resistance to flow.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 1, 'What is the wellbore storage coefficient?', '["The time in hours before the flow at the sandface reaches the rate recorded at the surface meter.", "The volume the wellbore accepts or gives up per psi of pressure change, in barrels per psi.", "The fraction of the produced volume that came from the wellbore rather than from the formation during the test.", "The compressibility of the wellbore fluid multiplied by the reservoir''s total compressibility."]'::jsonb, 1, 'For a wellbore full of liquid it is the volume times the fluid compressibility. For a well with a rising liquid level it is much larger, and that is the usual case on a surface shut-in.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 2, 'During pure wellbore storage, how does the pressure change behave?', '["Proportionally to the logarithm of elapsed time, which is why the semilog line extends back to time zero.", "Proportionally to the square root of elapsed time, because the wellbore empties through a restricted area.", "Proportionally to elapsed time, which is a unit slope on a log-log plot.", "It does not change at all until the storage volume has been produced and the reservoir takes over."]'::jsonb, 2, 'During pure storage the pressure change and its derivative are the same quantity, so on a log-log plot the two curves lie on top of each other. That coincidence is the most reliable diagnostic in well testing.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 3, 'Why does storage-affected data make a semilog fit steeper?', '["A quantity linear in time rises ever more steeply per cycle, where radial flow rises at a fixed rate.", "Because the storage period carries the skin''s pressure drop, which adds to the slope until the transient escapes it.", "Because the gauge is nearest the storage volume, so its readings are amplified during that period.", "Because the rate is still changing during storage, and a rising rate steepens any pressure response."]'::jsonb, 0, 'A steeper slope is a lower permeability, from the slope equation. That single fact drives every error in this module.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 4, 'How long does the semilog straight line take to begin after the unit slope ends?', '["About one cycle, which is the standard design rule for how long a buildup needs to run.", "It begins immediately, since the unit slope ending is the definition of storage having finished.", "About a quarter of a cycle, which is why most tests contain usable radial data within the first hour.", "Roughly one and a half logarithmic cycles, and longer on a well with a large storage coefficient and a large skin."]'::jsonb, 3, 'Choosing a window that starts where the unit slope ends is a standard error and it lands squarely in the steepest part of the transition.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 5, 'The buildup fitted over every point returns 23.12907021605519 mD against a planted 85. Why?', '["Because the least squares fit weights the late points too heavily, and the late points are boundary-affected.", "Because three quarters of those points are describing a wellbore rather than a reservoir.", "Because the producing time used in the Horner ratio was too short for the length of the shut-in.", "Because the analysis used the completed interval rather than the net pay as the thickness."]'::jsonb, 1, 'The data are correct and the fit is a proper least squares. The window is the error, and it is the only error.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 6, 'In the window walk, how does the permeability approach the planted value?', '["Monotonically from above, since removing points reduces the leverage of the late data on the fit.", "It oscillates around the planted value as points are removed, converging as the window narrows.", "Monotonically from below, without reaching it, because a trace of the transition always remains.", "It jumps to the planted value as soon as the last storage-affected point is excluded."]'::jsonb, 2, 'That is a bias, not a scatter. The classical semilog analysis of a storage-affected buildup systematically understates permeability, and the understatement does not average out over many tests.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 7, 'What happens to the sign of the skin across the window walk?', '["It starts negative, which says stimulated, and crosses zero into damage as the window narrows.", "It stays positive throughout, with only its magnitude changing as the fitted window changes.", "It starts positive and becomes negative, because narrowing the window raises the fitted permeability.", "It changes sign twice, once when storage is excluded and again when the fit becomes too short."]'::jsonb, 0, 'Not a change of magnitude but a change of conclusion, on the one question the test was run to settle. It is the same failure the fault fixture produces at the other end of a test.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 8, 'Why do the permeability error and the skin error reinforce rather than cancel?', '["Because both are computed from the same intercept, so any error in the intercept enters both identically.", "Because the skin is defined as a function of the permeability, so it inherits its error proportionally.", "Because the least squares fit minimises the total residual, which trades one error against the other.", "An inflated slope shrinks the skin formula''s first term, and a smaller permeability lifts its logarithmic term."]'::jsonb, 3, 'Both effects push the skin down. If they had opposite signs the result would look inconsistent and somebody would check; because they reinforce, the answer is a coherent and wrong reservoir description.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 9, 'What does an r squared of 0.9004033647584739 on this buildup indicate?', '["That the data carry gauge noise, which is what a coefficient below 0.99 normally means.", "That a line describes the chosen points reasonably well, and nothing about whether they were right.", "That the fitted window contains a boundary effect, since curvature at late time lowers the coefficient.", "That roughly ten percent of the pressure variation is unexplained, which is within normal test tolerance."]'::jsonb, 1, 'The permeability behind that coefficient is wrong by a factor of nearly four. Scatter is not the problem in a well test; curvature is, and r squared is a poor detector of it.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 10, 'In well test analysis, what range of r squared actually carries information?', '["Between 0.8 and 0.99, which is the range where a regression is normally judged in engineering.", "Any value above 0.95, since below that the fit should be rejected and the window reconsidered.", "Between about 0.999 and 0.99999, where the last two digits separate a usable answer from a wrong one.", "The range does not matter; only the standard error of the slope is informative for a well test."]'::jsonb, 2, 'The data are smooth, so any smooth curve is well approximated by a line over a limited range. The residuals stay small while the slope is badly wrong.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 11, 'Which check actually detects curvature in a semilog fit?', '["A plot of the residuals against time, where a systematic arc is obvious even when r squared is high.", "A higher-order polynomial fit, compared against the linear one by an information criterion.", "The standard error of the slope, which grows when the underlying relationship is not linear.", "Repeating the fit with a different least squares implementation to confirm the two agree."]'::jsonb, 0, 'It costs nothing and almost nobody does it. The proper tool is the pressure derivative, which turns a gentle bend into a visible slope change, and that belongs to the next tier.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 12, 'Why not narrow the semilog window as far as possible?', '["Because the late data are the noisiest, so a narrow late window has the largest random error.", "Too few points make the fit unstable, and narrowing from the front eventually admits the late data.", "Because the skin formula requires at least one full decade of data to evaluate the one-hour reference.", "Because a window shorter than the storage period cannot resolve the storage coefficient."]'::jsonb, 1, 'The right window is bounded at both ends by physics: after the storage transition, before the first boundary. Finding those bounds needs the derivative.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 13, 'What is the standard error of the slope good for, and what is it blind to?', '["It detects curvature in the fitted data, which is exactly what r squared cannot do.", "It measures how far the fitted line sits from the true radial line, which r squared alone cannot do.", "It quantifies the effect of the thickness uncertainty on the reported permeability.", "It turns scatter about the line into a permeability range, and is blind to the choice of regime."]'::jsonb, 3, 'On noiseless data it goes to zero regardless of how badly the window was chosen. On real data it is the honest way to attach a range, and it belongs in a report.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 14, 'Two engineers analyse this buildup and report 23 mD with a stimulated well, and a good reservoir with a damaged one. What happens next?', '["Both reports are filed and the discrepancy is resolved by running a second test on the same well.", "The first report is rejected because a negative skin is physically impossible in an unstimulated well.", "The first report sends capital to drilling more wells while the damage keeps being paid for.", "Neither report is actionable, so the field waits for a longer test with a downhole shut-in tool."]'::jsonb, 2, 'A negative skin is not impossible, which is exactly why it is not caught. It is implausible on a well with no fracture and no acid job, and asking what would have made it stimulated is a thirty-second check.'),
  ('welltest', 'beginner', 'module', 'm05-choosing-the-line', 15, 'What is the quickest sanity check on a reported negative skin?', '["Ask which known cause applies: a fracture, an acid job, deviation, or a thickness that was too small.", "Recompute the skin using the measured one-hour pressure rather than the fitted line''s value.", "Compare the reported permeability against the field''s mapped value and reject it if it differs.", "Check that the standard error of the slope is smaller than the slope itself, which rules out a bad fit."]'::jsonb, 0, 'If none of them applies, a negative skin is a reason to go back to the window rather than a result to report. It catches this error most of the time.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Summarised in one sentence, what does this tier establish?', '["A buildup is a more reliable test than a drawdown, because its rate is exactly zero and stays there.", "Wellbore storage can be removed from a test by shutting the well in downhole rather than at surface.", "The reported answer is a property of the chosen analysis window quite as much as it is of the well itself.", "The permeability from a semilog line is accurate to a few percent when the fit is done carefully enough."]'::jsonb, 2, 'Everything else in the tier is either the machinery that produces the numbers or the evidence for that claim.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 2, 'What is the semilog slope for this reservoir at the planted permeability?', '["21.520588235294117 psi per cycle, which is what the planted 85 mD implies at this rate and thickness.", "79.08878233809047 psi per cycle, which is what a least squares fit over every point returns.", "9.344117647058821 psi per cycle, which is the value the Bourdet derivative settles at in radial flow.", "162.6 psi per cycle, which is the constant in the slope equation evaluated at unit rate and thickness."]'::jsonb, 0, 'Any fit far from it is not radial flow. The 79.09 figure is what fitting every point gives, and 162.6 is a constant in the equation rather than a slope.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which pair of numbers describes what a defensible analysis of this buildup should report?', '["A permeability slightly above 85 mD and a skin slightly above plus 6.5, since the fit converges from above.", "A permeability a few percent below the planted 85 mD, and a skin a few tenths short of plus 6.5.", "Exactly 85 mD and exactly plus 6.5, since the fixture was generated from those values without noise.", "A permeability near 23 mD and a negative skin, which is what the least squares fit over the data gives."]'::jsonb, 1, 'The convergence is from below and it does not arrive, because even the last thirteen points carry a trace of the storage transition.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What can this tier NOT do, that the next one can?', '["Compute a skin, which requires the derivative''s plateau height rather than the semilog line''s position.", "Analyse a buildup, since the Horner transform is introduced only at the Professional level.", "Report a flow capacity, because separating it into permeability and thickness needs a log interpretation.", "Justify an analysis window from the data itself, which is what the pressure derivative is for."]'::jsonb, 3, 'Narrowing until the answer stops moving is the best available substitute, and it cannot tell you WHY a window is right or whether there is radial flow in the test at all.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 5, 'In the capstone, which permeability goes into the skin pressure drop?', '["The one you fitted and reported yourself, rather than the planted 85 mD the fixture was built from.", "The planted 85 mD, because the skin pressure drop is a property of the reservoir rather than of the fit.", "The average of the fitted and planted values, which is the standard convention for a derived quantity.", "The permeability from the drawdown analysis, since it is closer to the planted value than the buildup''s."]'::jsonb, 0, 'Every downstream quantity uses the upstream quantity you actually reported. Substituting the planted value gives an answer close enough that the error is easy to miss and outside tolerance.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Which two quantities in the capstone chain both depend on the fitted permeability?', '["The semilog slope and the extrapolated pressure, both of which come from the fitted line.", "The skin pressure drop, and the radius of investigation at the producing time.", "The skin and the extrapolated pressure, because both are read off the line''s position.", "The flow efficiency and the semilog slope, which is why the two are always reported together."]'::jsonb, 1, 'The slope and p star come from the fit directly and do not use k. The skin uses k, and then the skin pressure drop and the radius of investigation both use it again.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 7, 'On the Horner axis, where do you read the pressure the skin formula wants?', '["At a Horner ratio of 1, which is where the line is extrapolated to for the pressure at infinite shut-in.", "At a Horner ratio of 36, which is the producing time expressed on the transformed axis.", "At a Horner ratio of exactly 37, which is one hour of shut-in following 36 hours of production.", "At the first recorded point, whose Horner ratio is just over 3600 for this test."]'::jsonb, 2, 'A ratio of 1 gives p star. The reference for the skin is one hour of shut-in, and where that sits on the axis depends on the producing time.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Why does the capstone ask for full precision when this tier taught that two figures is honest?', '["Because the fixture is noiseless, so every digit the software prints is real.", "Because the tolerance is set by the gauge resolution, which is much finer than two figures.", "Because a certificate has to be defensible, and a rounded answer could not be audited later.", "Because the grader is checking that the analysis was run rather than estimated from a plot."]'::jsonb, 3, 'That is a different purpose from a report to a colleague, where the honest form is two or three figures and a stated range.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What is the flow efficiency of this well, roughly?', '["A little over a half, meaning the well delivers something over half of what an undamaged well would.", "A little over one, because the well is producing above the ideal rate for the drawdown it is being held at.", "Close to 0.9, which is normal for a well with a modest positive skin in good rock.", "It cannot be computed from a buildup, because the average pressure is not measured by one."]'::jsonb, 0, 'It is the sentence you would put at the top of a report. p star stands in for the average pressure here, which is standard for a well early in its life in a large reservoir.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What is p star on this buildup, relative to the initial 4800 psia?', '["About 20 psi below it, which is the depletion caused by the 36 hours of production that preceded the shut-in.", "Within a fraction of a psi of it, because the reservoir is infinite acting and very little has been produced.", "Well above it, because extrapolating an infinite-acting line always overshoots the true pressure.", "It cannot be compared, since p star is a pseudo-pressure rather than a pressure."]'::jsonb, 1, 'That is the buildup working well, and it is the easiest case there is. In a bounded, produced reservoir p star sits above the average pressure by an amount that needs geometry to compute.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which habit does this tier recommend fixing before moving on?', '["Report the standard error of the slope rather than r squared, since that error converts directly into a permeability range.", "Analyse every buildup twice, once with Horner and once with MDH, and quote the range between them.", "State the window, in hours and in points, alongside every permeability that you report.", "Compute the storage coefficient from the first recorded point before choosing any semilog window."]'::jsonb, 2, 'A permeability without the interval it was fitted over is not a result anybody can check. The second habit is to ask what would have made the answer physically sensible.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 12, 'A permeability from a semilog line is an average over what, exactly?', '["The permeability at the wellbore, which is what a core plug also measures on a smaller scale.", "The arithmetic mean of the permeability map over the drainage area of the well.", "The harmonic mean of the layer permeabilities, since flow in series controls the resistance.", "An average over the volume the transient reached, weighted in a way that is not simple."]'::jsonb, 3, 'In a layered reservoir with no crossflow the test returns something close to a thickness-weighted arithmetic mean, because the layers produce in parallel. In other geometries it returns something else.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What did the window walk show about r squared?', '["It reached 0.9997 while the permeability behind it was still 9 percent wrong.", "It fell as the window narrowed, because fewer points give a poorer fit.", "It stayed constant across every window, which is why it cannot be used to choose one.", "It crossed 0.99 at exactly the point where the storage transition ended."]'::jsonb, 0, 'The interesting range is between 0.999 and 0.99999, and the last two digits are the whole signal, which is the reverse of the usual instinct.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which comparison is worth making once you have a flow capacity from a test?', '["Against the core plug permeabilities from the same well, which measure the same rock directly.", "Against the flow capacity the log-derived permeability profile predicts over the same interval.", "Against nearby wells, since a field''s transmissibility should be uniform.", "Against the simulator''s assigned permeability, which is the value the test is meant to replace."]'::jsonb, 1, 'If the test capacity is higher, something is conducting that the logs did not see. If it is lower, something is not connected. Either way the disagreement is information.'),
  ('welltest', 'beginner', 'module', 'm06-the-associate-reading', 15, 'The two analyses of this well disagree by about one percent on permeability. What should the report say?', '["The buildup value, because a buildup has an exactly controlled rate and is therefore the more reliable test.", "The drawdown value, because it is a direct measurement rather than an analysis carrying a producing time.", "Both of the values, as a stated range, rather than an average presented as a single answer.", "The average of the two, since neither is preferred and averaging reduces the random error."]'::jsonb, 2, 'The disagreement is a property of the measurement rather than a mistake in one of them, and it is a useful estimate of the analysis uncertainty.'),
  ('welltest', 'beginner', 'final', null, 1, 'A colleague says the gauge measured a permeability of 82 mD. How do you correct them?', '["The gauge measures a flow capacity, and the permeability follows only after dividing by a net pay.", "The gauge measured pressures; the 82 mD is what somebody''s choice of fitting window turned them into.", "Nothing to correct: a downhole gauge with a rate meter does determine permeability directly.", "The gauge measured a slope, and permeability is what the slope equation returns from it."]'::jsonb, 1, 'A slope is not measured either; it is fitted to whichever points were selected. That selection is the decision the report has to state.'),
  ('welltest', 'beginner', 'final', null, 2, 'You are handed a test report with a permeability, a skin and an r squared, and nothing else. What is the first thing you ask for?', '["The pressure plot and the interval that was fitted, in hours and in points.", "The gauge calibration certificate, which sets the resolution the whole analysis inherits.", "The net pay used, since permeability is inversely proportional to it and it is often revised later.", "A second analysis by a different engineer, so that the two can be compared for consistency."]'::jsonb, 0, 'The net pay matters and it is the second question. The window is first because without it nothing in the report can be checked at all.'),
  ('welltest', 'beginner', 'final', null, 3, 'A test on a well flowing 450 stb/d records the rate as 405 by mistake. What does the reported permeability do?', '["It comes out ten percent high, because a smaller rate implies a smaller pressure drop for the same rock.", "It is unaffected, since the rate cancels between the slope and the skin terms of the analysis.", "It comes out ten percent low, and nothing in the analysis reveals the error.", "It comes out about twenty percent low, because the rate enters both the slope and the skin."]'::jsonb, 2, 'Permeability is proportional to rate. A rate ten percent low gives a permeability ten percent low, exactly, and silently.'),
  ('welltest', 'beginner', 'final', null, 4, 'A buildup runs 60 hours after 12 hours of production. Which analysis form is correct?', '["MDH, since the shut-in is long enough that the production before it has become negligible.", "Either, since the two differ only by a constant that shifts the line without tilting it.", "Agarwal equivalent time, because a buildup is always analysed on the transform that maps it onto a drawdown.", "Horner, because the producing time is not much larger than the shut-in time."]'::jsonb, 3, 'MDH is valid when tp is much greater than the shut-in time, so that the Horner ratio reduces to tp over dt. Here it is five times smaller and the approximation fails.'),
  ('welltest', 'beginner', 'final', null, 5, 'A well shows a semilog slope of 0.3 psi per cycle at 400 stb/d in a 40 ft sand. What should you check first?', '["The units, because a slope that small would imply a permeability of several thousand millidarcies.", "The window, since a slope that flat is what fitting only the last two or three points produces.", "The rate record, because a slope that small would need a rate an order of magnitude lower than recorded.", "The gauge, because a pressure resolution coarser than the change over a cycle flattens the fitted line."]'::jsonb, 0, 'A sanity check on the resulting permeability is the defence against a unit error, since the 162.6 constant cannot be derived at the desk.'),
  ('welltest', 'beginner', 'final', null, 6, 'A stimulated well reports a skin of minus 4. What does its equivalent wellbore radius look like?', '["About four times the actual radius, since the skin scales the radius linearly in this range.", "About 55 times the actual radius, because the effective radius is the actual one times the exponential of minus the skin.", "A quarter of the actual radius, because a negative skin corresponds to a restricted entry.", "The same as the actual radius, since the equivalent radius is defined only for positive skins."]'::jsonb, 1, 'The exponential of 4 is about 55. That is why a hydraulic fracture of half-length 250 ft behaves roughly like a skin around minus 5 or minus 6.'),
  ('welltest', 'beginner', 'final', null, 7, 'During a shut-in the wellbore keeps filling for two hours. What does the log-log plot look like over that period?', '["The derivative sits at half the pressure change, which is the ratio between them in every regime.", "The pressure change is flat while the derivative falls, because no reservoir fluid is arriving yet.", "The pressure change and its derivative lie on top of each other, on a line of slope 1.", "The derivative is negative, since the wellbore is filling rather than the reservoir depleting."]'::jsonb, 2, 'During pure storage the two are the same quantity. That coincidence on a unit slope is the most reliable diagnostic feature in well testing.'),
  ('welltest', 'beginner', 'final', null, 8, 'You narrow a semilog window and the permeability rises from 24 to 70 to 78 to 81 mD. What do you conclude?', '["The reservoir is heterogeneous, with better rock further from the well than close to it.", "The fit is becoming unstable as points are removed, which is why the answer keeps moving.", "The producing time is wrong, since a wrong tp makes the permeability drift as the window changes.", "The window is still admitting storage-affected data, and the answer has not yet stabilised."]'::jsonb, 3, 'The sequence approaches the truth monotonically from below and stops when you run out of points. Narrow until the answer stops moving, then justify the stop.'),
  ('welltest', 'beginner', 'final', null, 9, 'A report gives a skin of minus 2.7 on a well that has never been fractured or acidised. What do you do?', '["Go back to the analysis window, because none of the known causes of a negative skin applies here.", "Accept it, since a negative skin is common in naturally fractured reservoirs even without stimulation.", "Recompute it with the measured one-hour pressure, since the fitted line''s value is an extrapolation.", "Report it with a caveat, because the sign of a skin is not reliable at that magnitude anyway."]'::jsonb, 0, 'The known causes are a fracture, an acid job, a natural fracture intersected, deviation, or a thickness too small. If none applies, the window is the suspect.'),
  ('welltest', 'beginner', 'final', null, 10, 'Two engineers analyse the same buildup and report 23 mD with a stimulated well and 82 mD with a damaged one. Who made an arithmetic error?', '["The first, because a negative skin cannot arise from a correctly performed least squares fit.", "Neither. They fitted different windows and the equations did the rest.", "The second, because narrowing a window to thirteen points cannot support a four-figure answer.", "Both, since two correct analyses of one dataset are required to agree within a few percent."]'::jsonb, 1, 'That is the whole claim of this tier. The window is a decision rather than a calculation, and the answer depends on it strongly enough to invert a conclusion.'),
  ('welltest', 'beginner', 'final', null, 11, 'A field''s mapped permeability is 40 mD and a test reports 120. Which is the least likely explanation?', '["The well intersects a fracture or a thief zone that the log-derived profile did not capture.", "The net pay used in the analysis was much smaller than the interval actually contributing flow.", "The gauge over-read, because a constant pressure offset cancels out of the analysis entirely.", "The semilog window sat on a regime that is not radial flow, which can inflate a permeability."]'::jsonb, 2, 'A constant offset cancels from both the slope and the skin''s pressure difference, so it changes nothing. The other three are all real mechanisms.'),
  ('welltest', 'beginner', 'final', null, 12, 'What is the flow capacity if the semilog slope is 22 psi per cycle at 450 stb/d with B 1.25 and viscosity 0.9 cp?', '["About 82 millidarcy feet, which is the permeability before it is multiplied by the thickness.", "About 165 millidarcy feet, from the slope divided into the constant alone.", "It cannot be computed without the net pay, which enters the flow capacity directly.", "About 3700 millidarcy feet, from 162.6 times q B mu divided by the fitted slope."]'::jsonb, 3, 'The rearranged slope equation has no thickness on the right. That is why the flow capacity is the quantity a test determines and the permeability is a division you perform afterwards.'),
  ('welltest', 'beginner', 'final', null, 13, 'A petrophysicist revises the net pay from 45 ft to 54 ft. What happens to the reported values?', '["The permeability falls by about a sixth and the flow capacity does not change.", "Both fall by about a sixth, since the flow capacity is the product of the two.", "The permeability rises by about a fifth, because more pay means more capacity for the same rock.", "Neither changes, since the analysis fitted a pressure history rather than a thickness."]'::jsonb, 0, '45 over 54 is about 0.83. Reporting the flow capacity and the thickness used lets a reader redo the division without rerunning anything.'),
  ('welltest', 'beginner', 'final', null, 14, 'A well is completed across 15 ft of a 50 ft sand. What does using 15 ft in the slope equation do?', '["It gives the correct permeability of the completed interval, which is the useful quantity for inflow.", "It inflates the permeability and hides a real positive skin, both in the same direction.", "It deflates the permeability, because a smaller thickness makes the same capacity look worse.", "It has no effect once radial flow is established, since the transient drains the whole sand anyway."]'::jsonb, 1, 'The restricted entry belongs in the skin as a pseudoskin, not in the thickness. Both errors make the well look better than it is.'),
  ('welltest', 'beginner', 'final', null, 15, 'The buildup''s flowing pressure at shut-in is about 269 psi below the initial pressure, and the skin costs about 121 psi of that. What is the sentence for a manager?', '["The well has depleted the reservoir by 269 psi in 36 hours, which indicates a small compartment.", "The well would produce 45 percent more if the damage were removed, at the same flowing pressure.", "Roughly 45 percent of the pressure driving this well is being spent crossing near-well damage.", "The reservoir is contributing only 55 percent of the flow capacity the map assigned to it."]'::jsonb, 2, 'It is a pressure statement. Converting it to a rate gain needs the productivity index and the assumption that productivity is proportional to drawdown.'),
  ('welltest', 'beginner', 'final', null, 16, 'A gas well''s reported skin rises from 3 to 7 when it is tested at a higher rate. What does that mean?', '["The damage grew between the two tests, which is common when fines migrate at higher drawdowns.", "The first test used a thickness that was too large, which understated the skin.", "The higher-rate test reached radial flow sooner, so its window was better chosen.", "Part of the apparent skin is non-Darcy flow, which grows with rate and is not damage."]'::jsonb, 3, 'The apparent skin is the real skin plus a rate-dependent term. Separating them needs two rates, and a single-rate test returns only the sum.'),
  ('welltest', 'beginner', 'final', null, 17, 'Which of these belongs in a well test report alongside a permeability?', '["The flow capacity, the thickness used, its source, and the window that was fitted.", "The gauge serial number and calibration date, so the pressure record can be audited.", "The number of iterations the fit required and the convergence tolerance used.", "The reservoir''s mapped permeability, so the reader can see whether the test agrees with it."]'::jsonb, 0, 'Anything less and the number cannot be revised when the petrophysics is revised, which it will be.'),
  ('welltest', 'beginner', 'final', null, 18, 'Why is the extrapolation to a Horner ratio of one finite?', '["Because the pressure recovery is bounded above by the initial reservoir pressure.", "Because the axis is a logarithm of a ratio that is bounded below by one.", "Because the extrapolation stops at the last recorded point and is not projected beyond it.", "Because the semilog line has a finite slope, so any finite extrapolation gives a finite value."]'::jsonb, 1, 'The Horner ratio approaches one from above as the shut-in time goes to infinity, so the extrapolation to one is the pressure after an infinite shut-in.'),
  ('welltest', 'beginner', 'final', null, 19, 'A buildup after 36 hours of production is shut in for a month. How much further does it see than a shut-in of a few days?', '["Proportionally further, since the radius of investigation grows as the square root of shut-in time.", "About twice as far, because the equivalent time roughly doubles over that range.", "Very little, because the Agarwal equivalent time saturates at the producing time.", "It sees less, because the pressure change becomes too small to resolve against gauge drift."]'::jsonb, 2, 'If a test needs to reach a boundary, the production BEFORE the shut-in has to be long enough. Extending the shut-in past a few times tp buys almost nothing.'),
  ('welltest', 'beginner', 'final', null, 20, 'What is the practical consequence of p star sitting above the average pressure in a bounded reservoir?', '["It makes the permeability too high, because the extrapolation steepens the fitted line.", "It makes the skin too low, because the reference pressure for the skin is inflated.", "It has no consequence, since p star is used only as a consistency check between tests.", "Using it as the reservoir pressure overstates what is left in the tank."]'::jsonb, 3, 'The Matthews-Brons-Hazebroek and Dietz corrections convert p star to an average pressure using the drainage geometry, and neither is in this engine.'),
  ('welltest', 'beginner', 'final', null, 21, 'Two tests on one well over two years give p star values of 4800 and 4310 psia. What have you learned?', '["The reservoir has depleted, and the trend is informative even though neither value is the average pressure.", "The second analysis used a wrong producing time, since p star should not change on the same well.", "The permeability has fallen, since a lower extrapolated pressure means a poorer connection.", "Nothing, because p star is a property of a fitted line and two lines cannot be compared."]'::jsonb, 0, 'A falling p star over a sequence of tests on the same well is depletion. That is one of the three honest uses of the quantity.'),
  ('welltest', 'beginner', 'final', null, 22, 'A drawdown and a buildup on one well give 61.2 and 60.4 mD. What is the correct report?', '["The buildup, since its own rate is exactly controlled and the drawdown''s may have drifted.", "Both values, as a range, with a note that they are two measurements rather than one.", "The average of 61 mD, since neither analysis is preferred and averaging halves the error.", "The drawdown, since it is a direct measurement without a producing time in the transform."]'::jsonb, 1, 'A gap of one or two percent is a normal, healthy result and a useful estimate of the analysis uncertainty. Reporting four figures when two valid analyses differ in the second is false precision.'),
  ('welltest', 'beginner', 'final', null, 23, 'A drawdown and a buildup on one well give 83 and 41 mD. What do you investigate first?', '["The gauge, since a factor of two suggests a calibration error in one of the two records.", "The rate during the buildup, which should be zero and may not have been.", "The producing time used in the Horner analysis, which is the commonest cause of a large gap.", "The net pay, since a different thickness would have been used for the two analyses."]'::jsonb, 2, 'A wrong tp moves p star a lot and the permeability a little, so if the extrapolated pressure also looks wrong the producing time is the suspect. A boundary between the two tests is the other candidate.'),
  ('welltest', 'beginner', 'final', null, 24, 'Which statement about wellbore storage is correct?', '["It is confined to the first few minutes on any well with a downhole shut-in tool.", "Its effect can be removed from the data by subtracting the unit-slope line before fitting.", "It affects a buildup but not a drawdown, because a drawdown starts from a static wellbore.", "It lasts longer than most people expect, and the transition after it is longer still."]'::jsonb, 3, 'The classical rule is that the semilog line does not begin until roughly one and a half cycles after the unit slope ends. On this buildup that leaves thirteen usable points out of forty.'),
  ('welltest', 'beginner', 'final', null, 25, 'Why does a downhole shut-in tool help so much?', '["It cuts the stored volume to the few feet between the tool and the perforations.", "It removes the fluid column between the gauge and the surface, which is the source of the storage.", "It stops the reservoir flowing immediately, which a surface valve cannot do at any depth.", "It allows the pressure to be measured before the storage transient begins."]'::jsonb, 0, 'It can shorten the storage period by more than a decade of time, which converts a test with no usable radial data into one that has plenty.'),
  ('welltest', 'beginner', 'final', null, 26, 'A storage coefficient computed from a test comes out ten times the wellbore volume times the fluid compressibility. What does that suggest?', '["The gauge is reading a delayed pressure, which inflates the apparent storage coefficient.", "There is a liquid level or a gas cap in the annulus, so the well is not full of a single fluid.", "The rate meter is reading high, since storage is computed from the rate and the pressure change.", "The test was analysed on the wrong time axis, which scales the storage coefficient directly."]'::jsonb, 1, 'A well with a rising liquid level has a much larger storage coefficient than a full one, because the volume per unit length divided by the fluid gradient is far larger than a compressibility term.'),
  ('welltest', 'beginner', 'final', null, 27, 'An r squared of 0.9998 on a semilog fit. What does it tell you?', '["That the permeability is accurate to about two parts in ten thousand, which is the residual fraction.", "That the window contains no boundary effect at all, since a boundary would introduce visible curvature.", "That a line describes those points well, and nothing about whether the regime was radial flow.", "That the fit is acceptable, since anything above 0.999 is the usual accepted threshold for a well test."]'::jsonb, 2, 'On this buildup a window with an r squared of 0.9997 is still nine percent wrong on permeability. The interesting range is the last two digits.'),
  ('welltest', 'beginner', 'final', null, 28, 'Which check most reliably reveals curvature that r squared hides?', '["Comparing the fitted slope against the slope from a shorter sub-window of the same data.", "Computing the standard error of the slope and comparing it against the slope itself.", "Repeating the fit with a robust regression, which downweights the curved end of the data.", "Plotting the residuals of the fit against time and looking for a systematic arc in them."]'::jsonb, 3, 'It costs nothing and almost nobody does it. Comparing sub-windows is also useful and is the second-best check available without a derivative.'),
  ('welltest', 'beginner', 'final', null, 29, 'Two wells produce at 300 and 600 stb/d with the same skin factor. Which pays more pressure for its damage?', '["The second, because the skin pressure drop is proportional to rate while the skin factor is not.", "Neither, because the skin factor is defined to be rate-independent and it is the same for both.", "The first, because a lower rate means a longer residence time in the damaged zone.", "It depends on the permeability, which is not stated and enters the skin pressure drop."]'::jsonb, 0, 'Permeability does enter, but the question compares two wells with a stated difference in rate only. Damage matters more on high-rate wells for exactly this reason.'),
  ('welltest', 'beginner', 'final', null, 30, 'A well has a flow efficiency of 0.4 and produces 60 stb/d. Another has 0.4 and produces 6000. What do you do?', '["Treat them identically, since flow efficiency is designed to be comparable between wells.", "Report both the fraction and the skin pressure drop, because the ratio discards the scale.", "Prioritise the first well, since a low efficiency on a poor well suggests the damage is severe.", "Convert both to damage ratios, which weight the comparison by the size of the loss."]'::jsonb, 1, 'The damage ratio carries the same information and behaves badly, running to infinity as efficiency approaches zero. The honest pair is the fraction and the psi.'),
  ('welltest', 'beginner', 'final', null, 31, 'Which of these would NOT produce a positive skin?', '["Perforations that do not penetrate past the invaded and crushed zone around the wellbore.", "A flowing pressure below the bubble point, so that free gas is present near the wellbore.", "A well deviated at 45 degrees through the producing interval.", "A well completed across a fifth of the net pay in a reservoir with poor vertical permeability."]'::jsonb, 2, 'Deviation gives a negative pseudoskin, typically between minus 1 and minus 3, which can mask real damage on a deviated well.'),
  ('welltest', 'beginner', 'final', null, 32, 'Why is skin a residual rather than a measurement?', '["Because it is computed last in the chain, after the slope and the permeability.", "Because it is dimensionless, and a dimensionless quantity cannot be measured directly.", "Because it is read off the line''s position rather than its slope, and positions are less certain.", "Because it is defined as whatever pressure drop the ideal radial solution failed to predict."]'::jsonb, 3, 'Anything making the well harder to flow into than an ideal cylinder lands in it, which is why the diagnosis of what a skin means is separate from the arithmetic.'),
  ('welltest', 'beginner', 'final', null, 33, 'What does the radius of investigation formula need that the permeability determination does not?', '["Porosity and total compressibility, which come from logs, cores and fluid studies.", "The producing time, which the semilog analysis does not use at all.", "The skin, since the damaged zone slows the transient near the well.", "The wellbore radius, which sets the starting point the transient spreads from."]'::jsonb, 0, 'Both of those are inputs supplied from outside the test, and the test cannot separate them from each other.'),
  ('welltest', 'beginner', 'final', null, 34, 'Doubling the length of a test multiplies the radius investigated by roughly what?', '["2, because the disturbance travels outward at a constant speed set by the diffusivity.", "1.41, because the radius of investigation grows as the square root of elapsed time.", "1.26, because the disturbed volume rather than the radius grows linearly with time.", "It depends on the permeability, which sets how fast the transient propagates."]'::jsonb, 1, 'Permeability does set the scale, but not the exponent. That square root is why the last doubling of test time buys much less new rock than the first.'),
  ('welltest', 'beginner', 'final', null, 35, 'A buildup is analysed and the one-hour pressure is read off the recorded data rather than the fitted line. What happens?', '["The skin is unchanged, since the line passes through the data by construction at that time.", "The permeability comes out wrong, because the one-hour value enters the slope calculation.", "The skin comes out badly wrong, because at one hour the well is still storage-dominated.", "The extrapolated pressure moves, but the skin and permeability are unaffected."]'::jsonb, 2, 'The engine computes p1hr as the intercept plus the slope times the logarithm of tp plus one, which is the line''s value rather than any data point.'),
  ('welltest', 'beginner', 'final', null, 36, 'What does the phrase infinite acting describe?', '["A reservoir large enough that its boundaries will never be felt by any test.", "A well producing at a rate small enough that the pressure decline is negligible.", "A pressure response that continues to change indefinitely rather than stabilising.", "A stage of the test in which the disturbance has reached nothing that changes the geometry."]'::jsonb, 3, 'It is a statement about the test rather than about the reservoir. Every reservoir stops acting infinite eventually.'),
  ('welltest', 'beginner', 'final', null, 37, 'Why does this course teach on synthetic fixtures?', '["Because holding what an analysis reports against a known answer is the only way to see an interpretation error.", "Because real gauge data are too noisy for classical straight-line methods to work at all.", "Because the engine can only evaluate its own solutions and cannot read a real gauge file.", "Because real test data cannot legally be redistributed in training material."]'::jsonb, 0, 'The analyses run on a fixture are the same analyses that run on a real test, and the mistakes they make are the same mistakes.'),
  ('welltest', 'beginner', 'final', null, 38, 'In the capstone, the radius of investigation is graded at the fitted permeability rather than the planted one. Why does that matter?', '["Because the planted permeability is not disclosed until after the capstone is submitted.", "Because the difference between the two is small enough to look correct and large enough to fail.", "Because the radius of investigation is defined only for a fitted rather than a true permeability.", "Because the grader recomputes the whole chain and would reject an internally consistent answer."]'::jsonb, 1, 'The chain has to stay consistent: every downstream quantity uses the upstream quantity you actually reported.'),
  ('welltest', 'beginner', 'final', null, 39, 'What is the correct order of quantities in the capstone chain?', '["Permeability, then slope, then skin, since the permeability determines which window is right.", "Skin first, since it fixes the line''s position, and the slope follows from the position.", "Slope, then permeability, then the extrapolated pressure and the skin, then the derived quantities.", "The extrapolated pressure first, since it is the intercept and the rest of the fit follows from it."]'::jsonb, 2, 'The slope and the intercept come out of the fit together. Everything else is downstream of them, and the skin needs the permeability that the slope produced.'),
  ('welltest', 'beginner', 'final', null, 40, 'You have thirty seconds to sanity check a test result. What do you ask?', '["Whether the skin''s sign and the permeability''s magnitude are physically plausible for this well.", "Whether the r squared exceeds 0.999, which separates a usable fit from a poor one.", "Whether the fit used more than ten points, since fewer cannot support a four-figure answer.", "Whether the drawdown and buildup agree, which is the only independent check available."]'::jsonb, 0, 'A negative skin with no stimulation, a permeability an order of magnitude off the map, or an extrapolated pressure above the initial pressure. Each is a thirty-second check.'),
  ('welltest', 'beginner', 'final', null, 41, 'What does this tier certify that you can do?', '["Diagnose a flow regime from the shape of the pressure derivative on a log-log plot.", "Choose and justify a window, fit the line, and report the results with their caveats stated.", "Fit an analytical reservoir model to a whole pressure history by regression.", "Analyse a well from its production history without any shut-in at all."]'::jsonb, 1, 'The other three are the Professional and Expert tiers. What this tier covers is most of what is actually done with well tests in practice.'),
  ('welltest', 'beginner', 'final', null, 42, 'A test report states a permeability of 60.4137 mD. What is wrong with it?', '["Nothing, provided the fit''s standard error supports that many digits.", "The value should be quoted as a flow capacity instead, since the thickness is uncertain.", "Six figures on a quantity that two valid analyses of the same well disagree about in the second.", "It should be rounded to a whole number, which is the convention for reported permeabilities."]'::jsonb, 2, 'Software prints fifteen digits because floating point has fifteen digits. Copying them into a report implies a precision the measurement does not have.');
